import { createModel } from '../../../factory/create-model';
import { auditConfig } from '../../audit-config';
import { keepsTable } from '../../../database/database-config';

const shouldCreateModel = auditConfig.ENABLED || keepsTable('AuditLog');

const text = (maxLength: number) =>
  ({ type: 'string', required: false, maxLength }) as const;

// Written by the AuditService, exposed by the routes, service and policy of the application
export default shouldCreateModel
  ? createModel({
      name: 'AuditLog',
      // Generated by the AuditService, so an entry and its changes are written in one batch, in the order of time
      id: {
        type: 'string',
        generator: 'uuid(7)'
      },
      audit: {
        updatedAt: false,
        createdById: false
      },
      scalars: {
        category: { type: 'string', maxLength: 32 },
        source: { type: 'string', maxLength: 32 },
        action: text(255),
        method: text(16),
        route: text(1024),
        path: text(2048),
        query: { type: 'json', required: false },
        body: { type: 'json', required: false },
        status: { type: 'int', required: false },
        errorCode: text(255),
        // Milliseconds
        duration: { type: 'float', required: false },
        // No relation to the auth model, so the entries outlive their users
        userId: text(255),
        authType: text(32),
        apiKeyId: text(255),
        ip: text(64),
        userAgent: text(1024),
        requestId: text(255),
        traceId: text(64),
        model: text(255),
        resourceId: text(255),
        metadata: { type: 'json', required: false }
      },
      relations: {
        changes: {
          model: 'AuditChange',
          type: 'oneToMany',
          mappedBy: 'auditLog',
          required: false,
          input: {
            type: 'none'
          },
          output: {
            type: 'single'
          }
        }
      },
      index: [
        '-createdAt',
        ['category', '-createdAt'],
        ['userId', '-createdAt'],
        ['model', 'resourceId']
      ]
    })
  : undefined;
